# This program reads a book text file and analyzes chapter transitions.

import re
import sys

def read_book(file_path):
    with open(file_path, 'r') as f:
        return f.read()

def split_into_chapters(text):
    # Split by 'Chapter' followed by a number or roman numeral
    chapters = re.split(r'(?=Chapter\s+[IVXLCDM\d]+)', text, flags=re.IGNORECASE)
    if len(chapters) <= 1:
        return [text]  # No chapters found, treat whole as one
    return [ch.strip() for ch in chapters if ch.strip()]

def check_transitions(chapters):
    transition_phrases = ['meanwhile', 'however', 'furthermore', 'in addition', 'on the other hand', 'consequently', 'as a result']
    issues = []
    for i in range(1, len(chapters)):
        prev = chapters[i-1].split()[-10:]  # last 10 words of previous chapter
        curr = chapters[i].split()[:10]     # first 10 words of next chapter
        # Check if any transition phrase appears in first 10 words
        if not any(phrase in ' '.join(curr).lower() for phrase in transition_phrases):
            issues.append(f"Chapter {i} to {i+1}: missing transition phrase. Consider adding a bridging sentence.")
        # Check for abrupt break: if last sentence of prev is short and no transition
        if len(prev) < 5:
            issues.append(f"Chapter {i-1} ends abruptly. Consider concluding with a summary or hook.")
    return issues

def main():
    if len(sys.argv) != 2:
        print("Usage: python page_flow_analyzer.py <book.txt>")
        sys.exit(1)
    book_path = sys.argv[1]
    text = read_book(book_path)
    chapters = split_into_chapters(text)
    print(f"Found {len(chapters)} chapters/sections.")
    issues = check_transitions(chapters)
    if issues:
        print("Disruptions found:")
        for issue in issues:
            print(f"- {issue}")
    else:
        print("No major disruptions detected.")

if __name__ == '__main__':
    main()
